'use strict';
const warpCache=new Map(),warpJobs=new Map();let warpEpoch=0;
function warpKey(i,bpm){const p=pads[i];return i+':'+p.start+':'+p.end+':'+p.warpSetting+':'+p.warpMode+':'+p.warpPercent+':'+p.warpBeats+':'+(p.warpSetting==='sequence'?bpm:0)}
function warpRatio(p,bpm){return p.warpSetting==='sequence'?(p.warpBeats||4)*60/bpm/((p.end-p.start)*p.data.length/sr):(p.warpPercent||100)/100}
function effectiveWarp(i,bpm=tempo()){const p=pads[i];if(!p.warpSetting||p.warpSetting==='off')return p;const ratio=warpRatio(p,bpm);if(p.warpMode==='pitch')return {...p,warpRate:1/ratio,warpPitchMode:true};const entry=warpCache.get(warpKey(i,bpm));if(entry&&entry.data===p.data&&entry.right===p.right)return {...p,data:entry.left,right:entry.outputRight,start:0,end:1,loopStart:0};return p}
function stretchWarp(channels,ratio,ownerEpoch){return new Promise((resolve,reject)=>{const worker=new Worker('stretch-worker.js?v=13');const cleanup=()=>worker.terminate();worker.onerror=e=>{cleanup();reject(Error(e.message||'Calcul Warp impossible.'))};worker.onmessage=e=>{if(ownerEpoch!==warpEpoch){cleanup();reject(Error('Calcul Warp annulé : projet modifié.'));return}if(e.data.error){cleanup();reject(Error(e.data.error))}else if(e.data.channels){cleanup();resolve(e.data.channels)}};worker.postMessage({channels,ratio,rate:sr},channels.map(c=>c.buffer))})}
async function prepareWarp(i,bpm=tempo()){const p=pads[i];if(!p.warpSetting||p.warpSetting==='off'||p.warpMode==='pitch'||p.data.length===1)return;const key=warpKey(i,bpm),existing=warpCache.get(key);if(existing?.data===p.data&&existing?.right===p.right){warpCache.delete(key);warpCache.set(key,existing);return;}if(warpJobs.has(key))return warpJobs.get(key);const epoch=warpEpoch,sourceData=p.data,sourceRight=p.right;const job=(async()=>{const ratio=warpRatio(p,bpm),from=Math.floor(p.start*p.data.length),to=Math.floor(p.end*p.data.length),length=Math.round((to-from)*ratio);if(length>sr*60||to-from<sr*.08)throw Error('Warp '+padName(i)+' : sélection de 80 ms minimum et sortie de 60 s maximum.');const budget=[...warpCache.values()].reduce((n,e)=>n+e.left.byteLength+(e.outputRight?.byteLength||0),0)+length*4*(p.right?2:1);if(length*4*(p.right?2:1)>48*1024*1024)throw Error('Warp trop volumineux (48 Mo maximum).');let channels=[p.data.slice(from,to),...(p.right?[p.right.slice(from,to)]:[])],remaining=ratio;while(remaining>2.00001){channels=await stretchWarp(channels,2,epoch);remaining/=2}while(remaining<.49999){channels=await stretchWarp(channels,.5,epoch);remaining/=.5}channels=await stretchWarp(channels,Math.max(.5,Math.min(2,remaining)),epoch);if(epoch!==warpEpoch||pads[i]!==p||p.data!==sourceData||p.right!==sourceRight||warpKey(i,bpm)!==key)throw Error('Warp ignoré : sample modifié.');let used=[...warpCache.values()].reduce((n,e)=>n+e.left.byteLength+(e.outputRight?.byteLength||0),0),needed=channels.reduce((n,ch)=>n+ch.byteLength,0);for(const [old,e]of warpCache){if(used+needed<=48*1024*1024)break;const index=+old.split(':')[0];if(playing&&(old===warpKey(index,tempo())||warpTempoDesired!==null&&old===warpKey(index,warpTempoDesired)))continue;used-=e.left.byteLength+(e.outputRight?.byteLength||0);warpCache.delete(old)}if(used+needed>48*1024*1024)throw Error('Mémoire Warp pleine (48 Mo) : raccourcissez les samples ou arrêtez la lecture pour changer le tempo.');warpCache.set(key,{data:p.data,right:p.right,left:channels[0],outputRight:channels[1]||null});$('#warpState').textContent='Warp prêt · '+(ratio*100).toFixed(1)+' % · '+bpm+' BPM';})().finally(()=>{if(warpJobs.get(key)===job)warpJobs.delete(key)});warpJobs.set(key,job);return job}
async function prepareWarpOrder(order){for(const pattern of new Set(order)){const bpm=patternTempo(pattern);for(let i=0;i<pads.length;i++)if(pads[i].patterns[pattern]?.some(Boolean)){await prepareWarp(i,bpm);const link=pads[i].padLink;if(Number.isInteger(link)&&link>=0)await prepareWarp(Math.floor(i/16)*16+link,bpm)}}}
function clearWarpCache(){if(typeof cancelWarpTempo==='function')cancelWarpTempo();warpEpoch++;warpCache.clear();warpJobs.clear()}
function renderWarp(){const p=pads[selected];$('#warpSetting').value=p.warpSetting||'off';$('#warpMode').value=p.warpMode||'stretch';$('#warpPercent').value=p.warpPercent||100;$('#warpBeats').value=p.warpBeats||4;const pitch=p.warpSetting&&p.warpSetting!=='off'&&p.warpMode==='pitch';$('#pitch').disabled=!!pitch;$('#fine').disabled=!!pitch;if(!p.warpSetting||p.warpSetting==='off')$('#warpState').textContent='Warp désactivé.'}
for(const id of ['warpSetting','warpMode','warpPercent','warpBeats'])$('#'+id).onchange=async()=>{remember();const p=pads[selected];p.warpSetting=$('#warpSetting').value;p.warpMode=$('#warpMode').value;p.warpPercent=Math.max(50,Math.min(200,+$('#warpPercent').value||100));p.warpBeats=Math.max(.25,Math.min(128,+$('#warpBeats').value||4));clearWarpCache();renderWarp();changed();try{$('#warpState').textContent='Préparation du Warp…';await prepareWarp(selected);if(p.warpMode==='pitch')$('#warpState').textContent='Vitesse et hauteur liées, sans modifier le fichier original.';else if(p.warpSetting==='off')$('#warpState').textContent='Warp désactivé.'}catch(e){status(e.message);$('#warpState').textContent=e.message}};
renderWarp();

function warpReady(i,bpm=tempo()){const p=pads[i];if(!p.warpSetting||p.warpSetting==='off'||p.warpMode==='pitch'||p.data.length===1)return true;const e=warpCache.get(warpKey(i,bpm));return !!e&&e.data===p.data&&e.right===p.right}

// Prepare a tempo transaction, then commit on a bar boundary. Original samples stay untouched.
let warpTempoHold=null,warpTempoObserved=tempo(),warpTempoPending=null,warpTempoRequest=0,warpTempoTimer=null,warpTempoDesired=null;
function cancelWarpTempo(){clearTimeout(warpTempoTimer);warpTempoRequest++;warpTempoDesired=null;warpTempoHold=null;warpTempoPending=null;warpTempoObserved=Math.max(40,Math.min(240,Number($('#bpm').value)||110))}
function requestWarpTempo(value){const bpm=Math.max(40,Math.min(240,Number(value)||110));if(!playing||!pads.some(p=>p.warpSetting==='sequence'&&p.data.length>1)){warpTempoObserved=bpm;return false}if(warpTempoDesired===bpm)return true;warpTempoDesired=bpm;const request=++warpTempoRequest,owner=pads,ownerEpoch=warpEpoch;warpTempoHold=warpTempoHold??warpTempoObserved;warpTempoPending=null;clearTimeout(warpTempoTimer);$('#warpState').textContent='Préparation du tempo '+bpm+' BPM…';warpTempoTimer=setTimeout(async()=>{try{for(let i=0;i<owner.length;i++)if(owner[i].warpSetting==='sequence'){if(request!==warpTempoRequest||pads!==owner||ownerEpoch!==warpEpoch)return;await prepareWarp(i,bpm)}if(request!==warpTempoRequest||pads!==owner||ownerEpoch!==warpEpoch)return;if(!playing){warpTempoHold=null;warpTempoObserved=bpm;$('#bpm').value=bpm;return}warpTempoPending={bpm,request};$('#warpState').textContent=bpm+' BPM prêt · application à la prochaine mesure.'}catch(e){if(request!==warpTempoRequest)return;$('#bpm').value=warpTempoHold;warpTempoObserved=warpTempoHold;warpTempoHold=null;warpTempoDesired=null;status(e.message);$('#warpState').textContent=e.message}},100);return true}
function commitWarpTempo(time){if(!warpTempoPending)return;const {bpm,request}=warpTempoPending;if(request!==warpTempoRequest)return;warpTempoPending=null;warpTempoDesired=null;warpTempoHold=null;warpTempoObserved=bpm;$('#bpm').value=bpm;if(tempoMode==='sequence')sequenceTempos[currentPattern]=bpm;for(const v of [...voices]){if(v.stopTime!==undefined||!v.source.loop||pads[v.index].warpSetting!=='sequence')continue;const duration=v.source.buffer.duration,from=v.source.loopStart,to=v.source.loopEnd,span=to-from;if(span<=0)continue;const position=(v.playOffset??v.pad.start*duration)+Math.max(0,time-v.time)*v.source.playbackRate.value,phase=((position-from)%span+span)%span/span;v.release=5;stopVoice(v,time,true);trigger(v.index,time,ctx,audioBus,false,{_loopPhase:phase,_token:v.token,_linked:true,pitch:v.pad.pitch+(v.notePitch||0)+(v.pad.fine||0)/100,attack:5})}changed();$('#warpState').textContent='Warp actif · '+bpm+' BPM'}
const warpBpmChange=$('#bpm').onchange;$('#bpm').onchange=()=>{if(!requestWarpTempo($('#bpm').value))warpBpmChange()};
